class Solution(object):
    def longestMountain(self, A):
        """
        :type A: List[int]
        :rtype: int
        """
        if len(A) < 3:
            return 0
        dp1 = [0] * len(A)
        dp1[0] = 1
        for i in range(1, len(A)):
            if A[i] > A[i - 1]:
                dp1[i] = dp1[i - 1] + 1
            else:
                dp1[i] = 1
        dp2 = [0] * len(A)
        dp2[len(A) - 1] = 1
        for i in range(len(A) - 2, -1, -1):
            if A[i] > A[i + 1]:
                dp2[i] = dp2[i + 1] + 1
            else:
                dp2[i] = 1
        ans = 0
        for i in range(1, len(A) - 1):
            if dp1[i] > 1 and dp2[i] > 1:
                ans = max(ans, dp1[i] + dp2[i] - 1)
        return ans
